pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 firstFee, uint16 secondFee) public {
        // Restrict fees to valid range to avoid FeeRateTooHigh revert
        bound(firstFee, 0, 5000);
        bound(secondFee, 0, 5000);

        // First initialization
        c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            firstFee,
            bytes32(0),
            false,
            false
        );

        // Second initialization attempt (will revert because already initialized)
        try c.initialize(
            address(0),
            address(0),
            0,
            0,
            0,
            secondFee,
            bytes32(0),
            false,
            false
        ) {} catch {}

        // Property: after any sequence of initialize calls, feeRate must equal the last non-reverting _feeRate (firstFee)
        assertTrue(c.feeRate() == firstFee);
    }
}

